def P(t,style='BodyRU'): return Paragraph(t,styles[style])

def footer(canvas,doc):
    canvas.saveState(); canvas.setFont('DV',7.5); canvas.setFillColor(colors.HexColor('#666666'))
    canvas.drawString(16*mm,9*mm,'ЛокоПК | KHL | 22.09.2026 · прематч · коэффициенты перепроверить в Winline')
    canvas.drawRightString(198*mm,9*mm,f'стр. {doc.page}')
    canvas.restoreState()

def tbl(data,widths,header=True):
    t=Table(data,colWidths=widths,repeatRows=1 if header else 0,hAlign='LEFT')
    cmd=[('FONTNAME',(0,0),(-1,-1),'DV'),('FONTSIZE',(0,0),(-1,-1),8),('LEADING',(0,0),(-1,-1),10),('VALIGN',(0,0),(-1,-1),'TOP'),('GRID',(0,0),(-1,-1),0.35,colors.HexColor('#d7d7d7')),('LEFTPADDING',(0,0),(-1,-1),4),('RIGHTPADDING',(0,0),(-1,-1),4),('TOPPADDING',(0,0),(-1,-1),4),('BOTTOMPADDING',(0,0),(-1,-1),4)]
    if header: cmd += [('BACKGROUND',(0,0),(-1,0),colors.HexColor('#0b5d3b')),('TEXTCOLOR',(0,0),(-1,0),colors.white),('FONTNAME',(0,0),(-1,0),'DVB')]
    for r in range(1,len(data)):
        if r%2==0: cmd.append(('BACKGROUND',(0,r),(-1,r),colors.HexColor('#f5f8f6')))
    t.setStyle(TableStyle(cmd)); return t

